# Security cheque workflow only; all existing payment paths remain unchanged.
security_states = [
    "Prepare Security Cheque",
    "Pending Security Cheque - Chkr",
    "Pending Security Cheque - App",
    "Handover Security Cheque",
    "Security Cheque Issued"
]
previous_doc = doc.get_doc_before_save()
previous_state = previous_doc.get("workflow_state") if previous_doc else None
current_state = doc.get("workflow_state")

if current_state in security_states or previous_state in security_states or frappe.utils.cint(doc.get("is_security_cheque")):
    if current_state not in security_states:
        raise frappe.ValidationError("Security cheques must use the security cheque workflow.")
    if doc.docstatus != 0:
        raise frappe.ValidationError("Security cheque Payment Entries must remain in Draft and cannot be submitted.")
    if doc.mode_of_payment != "Cheque":
        raise frappe.ValidationError("Mode of Payment must remain Cheque for a security cheque.")
    if previous_state in security_states and current_state not in security_states:
        raise frappe.ValidationError("A security cheque cannot be moved into the ordinary payment workflow.")
    if current_state == "Security Cheque Issued":
        attachment_filters = {
            "attached_to_doctype": "Payment Entry",
            "attached_to_name": doc.name,
            "is_folder": 0
        }
        if doc.get("cheque_leaf"):
            cheque = frappe.get_doc("Cheque Leaf", doc.cheque_leaf)
            if cheque.get("signature_confirmed_on"):
                attachment_filters["creation"] = [">=", cheque.signature_confirmed_on]
        attachments = frappe.get_all(
            "File",
            filters=attachment_filters,
            fields=["name"],
            limit_page_length=1
        )
        if not attachments:
            raise frappe.ValidationError("Attach the security cheque copy before confirming handover.")

if current_state in security_states:
    doc.is_security_cheque = 1
